beforeSaveCustomScript:
// ============================================
// PART 1: License Key Formatting (4-character groups)
// ============================================

// Format perpetual license key (4-char groups)
if (perpetual != '' && perpetual != null) {
    $cleaned = string\replace(string\replace(perpetual, '-', ''), ' ', '');
    $length = string\length($cleaned);
    
    if ($length == 16) {
        perpetual = string\concatenate(
            string\substring($cleaned, 0, 4), '-',
            string\substring($cleaned, 4, 4), '-',
            string\substring($cleaned, 8, 4), '-',
            string\substring($cleaned, 12, 4)
        );
    } else if ($length == 20) {
        perpetual = string\concatenate(
            string\substring($cleaned, 0, 4), '-',
            string\substring($cleaned, 4, 4), '-',
            string\substring($cleaned, 8, 4), '-',
            string\substring($cleaned, 12, 4), '-',
            string\substring($cleaned, 16, 4)
        );
    } else if ($length == 25) {
        perpetual = string\concatenate(
            string\substring($cleaned, 0, 5), '-',
            string\substring($cleaned, 5, 5), '-',
            string\substring($cleaned, 10, 5), '-',
            string\substring($cleaned, 15, 5), '-',
            string\substring($cleaned, 20, 5)
        );
    } else if ($length > 4) {
        // Generic: add dashes every 4 characters
        $formatted = '';
        $i = 0;
        while ($i < $length) {
            $chunk = string\substring($cleaned, $i, 4);
            $formatted = string\concatenate($formatted, $chunk);
            $i = $i + 4;
            if ($i < $length) {
                $formatted = string\concatenate($formatted, '-');
            }
        }
        perpetual = $formatted;
    }
}

