// ============================================
// PART 2: Expiry Date & Status Calculation
// ============================================

if (expiryDate != null) {
    daysRemaining = datetime\diff(expiryDate, datetime\now(), 'days');
    
    if (daysRemaining > 30) {
        status = 'Active';
    } else if (daysRemaining >= 0 && daysRemaining <= 30) {
        status = 'Expiring Soon';
    } else {
